do $test$
declare tid uuid;other_trip uuid;own uuid;mem uuid;receiver uuid;req uuid:=gen_random_uuid();transfer_req uuid:=gen_random_uuid();cid uuid:=gen_random_uuid();eid uuid:=gen_random_uuid();other_eid uuid:=gen_random_uuid();tok uuid;n integer;before_money integer;
begin
 select owner_id into own from public.trips where name='ทดสอบ' limit 1;
 select id into mem from public.profiles where id<>own limit 1;
 select id into receiver from public.profiles where id not in (own,mem) limit 1;
 if receiver is null then raise exception 'Requires three test profiles';end if;
 begin
 insert into public.trips(owner_id,name,start_date,end_date,status)values(own,'ทดสอบ · สิทธิ์แยกการเงิน',current_date+1,current_date+2,'planning')returning id into tid;
 insert into public.trip_members(trip_id,user_id,trip_role)values(tid,own,'owner'),(tid,mem,'treasurer'),(tid,receiver,'member');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mem,'role','authenticated')::text,true);
 if not public.trip_finance_permission(tid,'fund') or not public.trip_finance_permission(tid,'approve') or not public.trip_finance_permission(tid,'confirm') then raise exception 'Legacy treasurer lost permissions';end if;
 begin perform public.set_trip_member_access(tid,receiver,'planner','{}',gen_random_uuid());raise exception 'Member changed access';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 perform public.set_trip_member_access(tid,mem,'planner','{"fund":false,"approve":false,"confirm":true}',req);
 perform public.set_trip_member_access(tid,mem,'planner','{"fund":false,"approve":false,"confirm":true}',req);
 if (select count(*) from public.trip_activity_log where trip_id=tid and request_key=req)<>1 then raise exception 'Duplicate access audit';end if;
 update public.trips set members_can_create_polls=false,members_can_add_collections=false where id=tid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',receiver,'role','authenticated')::text,true);
 begin perform public.trip_poll_save(tid,null,'ไม่ควรสร้าง','{}','[{"name":"A"},{"name":"B"}]','open');raise exception 'Member bypassed poll setting';exception when insufficient_privilege then null;end;
 begin perform public.save_collection_request(tid,cid,jsonb_build_object('title','ไม่ควรสร้าง','receiver_id',receiver,'amounts',jsonb_build_object(receiver,100)));raise exception 'Member bypassed collection setting';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mem,'role','authenticated')::text,true);
 if public.trip_fund_manager(tid) or public.trip_finance_permission(tid,'approve') or not public.trip_finance_permission(tid,'confirm') then raise exception 'Finance permissions coupled to planner';end if;
 tok:=public.trip_poll_save(tid,null,'Planner สร้างได้','{}','[{"name":"A"},{"name":"B"}]','open');
 begin perform public.trip_fund_action(tid,'contribution',jsonb_build_object('title','ไม่ควรสร้าง','amounts',jsonb_build_object(mem,100),'custodian_id',mem),gen_random_uuid());raise exception 'Planner accessed fund';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 insert into public.expenses(id,trip_id,title,amount,paid_by,category,created_by,approval_status)values(eid,tid,'ทดสอบสิทธิ์ตรวจรายจ่าย',100,own,'อื่น ๆ',own,'pending');
 perform public.save_collection_request(tid,cid,jsonb_build_object('title','ผู้รับธรรมดา','receiver_id',receiver,'amounts',jsonb_build_object(own,10000,mem,5000)));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mem,'role','authenticated')::text,true);
 begin perform public.review_expense(eid,'approved');raise exception 'Confirmation-only user approved expense';exception when others then if sqlerrm='Confirmation-only user approved expense' then raise;end if;end;
 perform public.confirm_collection_received(cid,mem,50);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',receiver,'role','authenticated')::text,true);
 perform public.confirm_collection_received(cid,own,100);
 if (select count(*) from public.collection_payments where collection_id=cid and status='paid')<>2 then raise exception 'Ordinary receiver or delegated confirmer failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 perform public.set_trip_member_access(tid,mem,'planner','{"fund":false,"approve":true,"confirm":false}',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mem,'role','authenticated')::text,true);
 perform public.review_expense(eid,'approved');
 if not exists(select 1 from public.expenses where id=eid and approval_status='approved' and reviewed_by=mem) then raise exception 'Explicit approver could not review';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 perform public.set_trip_member_access(tid,mem,'planner','{"fund":true,"approve":false,"confirm":false}',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mem,'role','authenticated')::text,true);
 if not public.trip_fund_manager(tid) or public.trip_finance_permission(tid,'approve') or public.trip_finance_permission(tid,'confirm') then raise exception 'Fund-only user inherited other finance rights';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 update public.trips set receipt_required_over=50 where id=tid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',receiver,'role','authenticated')::text,true);
 begin insert into public.expenses(trip_id,title,amount,paid_by,category,created_by,approval_status)values(tid,'ขาดใบเสร็จ',100,receiver,'อื่น ๆ',receiver,'approved');raise exception 'Missing receipt accepted';exception when others then if sqlerrm='Missing receipt accepted' then raise;end if;end;
 insert into public.expenses(trip_id,title,amount,paid_by,category,created_by,approval_status)values(tid,'รออนุมัติจริง',10,receiver,'อื่น ๆ',receiver,'approved');
 if exists(select 1 from public.expenses where trip_id=tid and title='รออนุมัติจริง' and approval_status<>'pending') then raise exception 'Member bypassed approval';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'role','authenticated')::text,true);
 begin
 update public.trip_members set trip_role='member' where trip_id=tid and user_id=own;
 set constraints member_owner_consistency immediate;
 raise exception 'Ownerless trip accepted';
 exception when others then if sqlerrm='Ownerless trip accepted' then raise;end if;end;
 set constraints member_owner_consistency deferred;
 begin perform public.remove_trip_member(tid,own);raise exception 'Owner removed self';exception when others then if sqlerrm='Owner removed self' then raise;end if;end;
 begin perform public.transfer_trip_ownership(tid,receiver,'ผิดชื่อ',transfer_req);raise exception 'Unconfirmed transfer';exception when others then if sqlerrm='Unconfirmed transfer' then raise;end if;end;
 perform public.transfer_trip_ownership(tid,receiver,'ทดสอบ · สิทธิ์แยกการเงิน',transfer_req);
 perform public.transfer_trip_ownership(tid,receiver,'ทดสอบ · สิทธิ์แยกการเงิน',transfer_req);
 set constraints member_owner_consistency,trip_owner_consistency immediate;
 set constraints member_owner_consistency,trip_owner_consistency deferred;
 if (select owner_id from public.trips where id=tid)<>receiver or (select trip_role from public.trip_members where trip_id=tid and user_id=own)<>'member' or (select count(*) from public.trip_members where trip_id=tid and trip_role='owner')<>1 then raise exception 'Ownership inconsistent';end if;
 if public.trip_finance_permission(tid,'approve') or (select count(*) from public.trip_activity_log where trip_id=tid and request_key=transfer_req)<>1 then raise exception 'Former owner retained access or transfer duplicated';end if;
 begin perform public.set_trip_member_access(tid,mem,'member','{}',gen_random_uuid());raise exception 'Former owner changed permissions';exception when insufficient_privilege then null;end;
 raise exception using errcode='PT007',message='rollback member access fixtures';
 exception when sqlstate 'PT007' then null;end;
 raise notice 'Settings/member/finance/ownership assertions passed; fixtures rolled back';
end $test$;
